CREATE OR REPLACE FUNCTION public.pair_refuses(p_world uuid, a creature, b creature)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare c creature; stage text;
begin
  foreach c in array array[a, b] loop
    stage := age_of(c.born, old_of(c), age_pace(c));
    if stage <> 'grown' then
      return c.name || case when stage = 'young' then ' is not grown.' else ' is too old.' end;
    end if;
    if c.hunger < 0.5 then return c.name || ' is too hungry: feed it first.'; end if;
    if c.bred_at is not null and now() - c.bred_at < make_interval(secs => breed_rest()) then
      return c.name || ' bred recently: '
        || clock_left(breed_rest() - extract(epoch from (now() - c.bred_at))) || ' left.';
    end if;
    if c.due is not null then return c.name || ' is already pregnant.'; end if;
  end loop;
  return null;
end $function$
